TLM.f("Sancti/09-18",{"officium":"S. Josephi de Cupertino Confessoris","rule":["vide C5;","9 lectiones"],"fallback":"Commune/C5","from":{"Tractus":"Commune/C5"},"sections":{"Introitus":[{"k":"ref","la":"Eccli 1:14-15"},{"k":"text","la":"Diléctio Dei honorábilis sapiéntia: quibus autem apparúerit in visu, díligunt eam in visióne et in agnitióne magnálium suórum."},{"k":"ref","la":"Ps 83:2"},{"k":"text","la":"Quam dilécta tabernácula tua, Dómine virtútum! concupíscit, et déficit ánima mea in átria Dómini."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Diléctio Dei honorábilis sapiéntia: quibus autem apparúerit in visu, díligunt eam in visióne et in agnitióne magnálium suórum."}],"Oratio":[{"k":"text","la":"Deus, qui ad unigénitum Fílium tuum exaltátum a terra ómnia tráhere disposuísti: pérfice propítius; ut, méritis et exémplo seráphici Confessóris tui Joséphi, supra terrénas omnes cupiditátes eleváti, ad eum perveníre mereámur:"},{"k":"macro","name":"Qui tecum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Corínthios"},{"k":"ref","la":"1 Cor 13:1-8"},{"k":"text","la":"Fratres: Si linguis hóminum loquar et Angelorum, caritátem autem non hábeam, factus sum velut æs sonans aut cýmbalum tínniens. Et si habúero prophetiam, et nóverim mystéria ómnia et omnem sciéntiam: et si habúero omnem fidem, ita ut montes tránsferam, caritátem autem non habúero, nihil sum. Et si distribúere in cibos páuperum omnes facultátes meas, et si tradídere corpus meum, ita ut árdeam, caritátem autem non habúero, nihil mihi prodest. Cáritas pátiens est, benígna est: cáritas non æmulátur, non agit pérperam, non inflátur, non est ambitiósa, non quærit quæ sua sunt, non irritátur, non cógitat malum, non gaudet super iniquitáte, congáudet autem veritáti: ómnia suffert, ómnia credit, ómnia sperat, ómnia sústinet. Cáritas numquam éxcidit: sive prophétiæ evacuabúntur, sive linguæ cessábunt, sive sciéntia destruétur."}],"Graduale":[{"k":"ref","la":"Ps 20:4-5"},{"k":"text","la":"Dómine, prævenísti eum in benedictiónibus dulcédinis: posuísti in cápite ejus corónam de lápide pretióso."},{"k":"text","la":"Vitam pétiit a te, et tribuísti ei longitudinem dierum in sǽculum, et in sǽculum sǽculi. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Eccle 11:13"},{"k":"text","la":"Oculus Dei respéxit illum in bono, et eréxit eum ab humilitáte ipsíus, et exaltávit caput ejus. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Eccli 11:13"},{"k":"text","la":"Oculus Dei respéxit illum in bono, et eréxit eum ab humilitáte ipsíus, et exaltávit caput ejus. Allelúja"},{"k":"ref","la":"Ps 45:9"},{"k":"text","la":"Amávit eum Dóminus, et ornávit eum: stolam glóriæ índuit eum. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 91:13; 91:14"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur in domo Dómini."},{"k":"ref","la":"Ps 91:3"},{"k":"text","la":"Ad annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem."},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 22:1-14"},{"k":"text","la":"In illo témpore: Loquebátur Jesus princípibus sacerdótum et pharisǽis in parábolis, dicens: Símile factum est regnum cœlórum hómini regi, qui fecit núptias fílio suo. Et misit servos suos vocáre invitátos ad nuptias, et nolébant veníre. Iterum misit álios servos, dicens: Dícite invitátis: Ecce, prándium meum parávi, tauri mei et altília occísa sunt, et ómnia paráta: veníte ad núptias. Illi autem neglexérunt: et abiérunt, álius in villam suam, álius vero ad negotiatiónem suam: réliqui vero tenuérunt servos ejus, et contuméliis afféctos occidérunt. Rex autem cum audísset, iratus est: et, missis exercítibus suis, pérdidit homicídas illos et civitátem illórum succéndit. Tunc ait servis suis: Núptiæ quidem parátæ sunt, sed, qui invitáti erant, non fuérunt digni. Ite ergo ad exitus viárum et, quoscúmque invenéritis, vocáte ad núptias. Et egréssi servi ejus in vias, congregavérunt omnes, quos invenérunt, malos et bonos: et implétæ sunt núptiæ discumbéntium. Intrávit autem rex, ut vidéret discumbéntes, et vidit ibi hóminem non vestítum veste nuptiáli. Et ait illi: Amíce, quómodo huc intrásti non habens vestem nuptiálem? At ille obmútuit. Tunc dixit rex minístris: Ligátis mánibus et pédibus ejus, míttite eum in ténebras exterióres: ibi erit fletus et stridor déntium. Multi enim sunt vocáti, pauci vero elécti."}],"Offertorium":[{"k":"ref","la":"Ps 34:13"},{"k":"text","la":"Ego autem, cum mihi molésti essent, induébar cilício. Humiliábam in jejúnio ánimam meam: et orátio mea in sinu meo convertétur."}],"Secreta":[{"k":"text","la":"Laudis tibi, Dómine, hóstias immolámus in tuórum commemoratióne Sanctórum: quibus nos et præséntibus éxui malis confídimus et futúris."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 68:30-31"},{"k":"text","la":"Ego sum pauper et dolens: salus tua, Deus, suscépit me. Laudábo nomen Dei cum cantico: et magnificábo eum in laude."}],"Postcommunio":[{"k":"text","la":"Refécti cibo potúque cœlésti, Deus noster, te súpplices exorámus: ut, in cujus hæc commemoratióne percépimus, ejus muniámur et précibus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"95a9ef2bdc49698d":{"t":"Sir 1, 14-15, Ps 83, 2\n(Sir 1, 14-15) Ljubav Božja donosi čast i mudrost. Tko shvati i upozna njezinu veličinu, zagrijat će se njegovo srce. (Ps 83, 2) Kako su mili stanovi tvoji, Gospodine vojska! Duša moja čezne i gine za dvorovima Gospodnjim.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Sir 1, 14-15) Ljubav Božja donosi čast i mudrost. Tko shvati i upozna njezinu veličinu, zagrijat će se njegovo srce."},"f6a95d08ae35d313":{"t":"<i>Pomolimo se</i>.\nBože, koji si odredio da sve privučeš k jedinorodenom Sinu svome podignutom sa zemlje, učini milostivo, da po zaslugama i primjeru serafskog priznavaoca tvoga Josipa zavrijedimo uzdignuti se nad sve zemaljske želje i doći k onome\n<i>koji s Tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"c8d4ee4b57027dbd":{"t":"1 Kor 13, 1-8\nČitanje Poslanice bl. Pavla apostola Korinćanima. Braćo: Kad bih govorio sve ljudske i anđeoske jezike, a ljubavi ne bih imao, bio bih kao trublja ili praporac što zveči. I kad bih imao dar proroštva i razumio sve tajne i sve znanosti, i kad bih imao jaku vjeru da bih mogao premještati brda, a ljubavi ne bih imao, bio bih ništa. I kad bih sav svoj imetak razdijelio siromasima i svoje tijelo predao da se sažeže, a ljubavi ne bih imao, ništa mi ne bi koristilo. Ljubav je strpljiva, ljubav je dobrostiva, ljubav ne zavidi, ne hvali se, ne uznosi se, ne teži za čašću, ne traži svoje, ne uznemiruje se, ne smišlja zla, ne veseli se nepravdi, a raduje se istini. Sve podnosi, sve vjeruje, svemu se nada, sve trpi. Ljubav nikad ne prestaje, a proroštva će prestati, jezici će umuknuti, znanja će nestati."},"d14da2ab1ad90159":{"t":"Ps 20, 4-5\nGospodine, pretekao si ga obilnim blagoslovima, na glavu si mu stavio krunu od dragog kamenja. U tebe je tražio život, i ti si mu dao dug život u vijeke vjekova.\n\nSir 11, 13\n<i>Aleluja</i>, <i>aleluja</i>.\nOko ga je Božje ljubazno pogledalo. Bog ga je podigao iz poniženja i uzvisio. <i>Aleluja</i>.","v":"∅ → et in seculum"},"2c1e7be4baae2775":{"t":"Mt 22, 1-14\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme govoraše Isus svećeničkim prvacima i farizejima u poredbama: Nebesko je kraljevstvo slično vladaru koji priredi svadbu svojemu sinu, pa posla svoje sluge da pozovu uzvanike na svadbu. Ali uzvanici nisu htjeli doći. Tada posla druge sluge i reče im: Kažite uzvanicima: Pripravio sam gozbu, moji su junci i utovljenici zaklani, i sve je pri pravljeno; dođite na svadbu. Ali oni nisu marili za to, nego pođoše netko u svoje polje, netko u svoju trgovinu, a ostali uhvatiše njegove sluge pa ih pogrdiše i ubiše. Kad to ču vladar, rasrdi se. On pošalje svoju vojsku; te pogubi one ubojice, a grad njihov spali. Tada reče svojim slugama: Gozba je doista pripremljena; ali pozvani nisu bili dostojni. Pođite zato na raskršća putova i pozovite na svadbu koga god nađete. Njegove sluge izađoše na putove te dovedoše sve koje nađoše zle i dobre. I svadbena se dvorana napuni gostiju. Kad uđe vladar da vidi goste, ugleda ondje jednoga koji nije bio obučen u svadbeno ruho. Vladar ga upita: Prijatelju, kako si amo ušao bez svadbenoga ruha? A on ušuti. Tada vladar zapovjedi slugama: Svežite mu ruke i noge i bacite ga van u tamu. Ondje će biti plač i škrgut zuba. Mnogo je zvanih, ali je malo izabranih."},"d71d7380e6e919e2":{"t":"Ps 34, 13\nKad su mi dosađivali, oblačio sam se u kostrijet, ponizivao sam u postu dušu i molitva se moja vraćala k srcu mojemu."},"18a58d3552d982fb":{"t":"Posvećujemo ti, Gospodine, žrtve hvale na spomen tvojih svetih i uzdamo se da ćeš nas po njima izbaviti od sadašnjih i od budućih zala.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"3832b24e17f8336c":{"t":"Ps 68, 30-31\nSiromah sam i jadan. Tvoja me je pomoć, Bože, zaštitila. Slavit ću pjesmom ime Božje i veličat ću ga hvalospjevom."},"77eef81bf0c58a4e":{"t":"<i>Pomolimo se</i>.\nOkrijepljeni nebeskim jelom i pićem ponizno te molimo, Bože naš, da budemo zaštićeni molitvama onoga na čiji smo to spomen primili.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
